<?php require_once __DIR__.'/../includes/bootstrap.php';require_role(['member']);verify_csrf();$uid=(int)current_user()['id'];$bid=(int)($_POST['book_id']??0);try{$conn->begin_transaction();$s=$conn->prepare('SELECT id,is_archived FROM books WHERE id=? FOR UPDATE');$s->bind_param('i',$bid);$s->execute();$b=$s->get_result()->fetch_assoc();if(!$b||$b['is_archived'])throw new Exception('Book not found or archived.');$s=$conn->prepare("SELECT id FROM reservations WHERE user_id=? AND book_id=? AND status IN('pending','approved','ready') FOR UPDATE");$s->bind_param('ii',$uid,$bid);$s->execute();if($s->get_result()->num_rows)throw new Exception('You already have an active reservation for this book.');$s=$conn->prepare("SELECT id FROM borrowings WHERE user_id=? AND book_id=? AND status IN('pending','approved','borrowed')");$s->bind_param('ii',$uid,$bid);$s->execute();if($s->get_result()->num_rows)throw new Exception('You already have an active borrowing request or loan for this book.');$s=$conn->prepare("INSERT INTO reservations(user_id,book_id,status) VALUES(?,?,'pending')");$s->bind_param('ii',$uid,$bid);$s->execute();$id=$conn->insert_id;$conn->commit();log_activity($conn,$uid,'reservation_requested','Reservation #'.$id.', book ID '.$bid);flash('success','Reservation submitted. Your place in the queue is based on request order.');}catch(Throwable $e){$conn->rollback();flash('error',$e->getMessage());}redirect('reservations.php');
